    ချိတ်ဆက်ပုံတန်ဖိုး = {'timeout': 'လုပ်ဆောင်မှုအချိန်လွန်', 'x': 'xတည်နေရာအမှတ်', 'msg': 'ကွန်ရက်စာ', 'i': 'အစဉ်အမှတ်', 'reply': 'အကြောင်းပြန်ချက်', 'call': 'ခေါ်လုပ်', 'args': 'ပေးအချက်အခင်းအကျင်း', 'chunk': 'အစိတ်အပိုင်း', 'data': 'ဒေတာ', 'proc': '실행과정', 'long_text': 'ရှည်စာသား', 'restored': '복원자료', 'send': 'ပို့', 'file': 'ဖိုင်', 'main': 'လုပ်ဆောင်', 'found': 'ရလဒ်ရှာဖွေ', 'ROOT': 'စီမံကိန်းအမြစ်', 'text': 'စာသား', 'marker': '확인표시', 'command': 'အမိန့်', 'expected': '예상결과', 'pixel': 'ပုံမှတ်', 'shell': 'အမိန့်ဝင်း', 'poll': '준비살피미', 'transcript': '대화기록', 'end': 'အဆုံးအရွေ့', 'image': 'စက်ကုဒ်ပုံရိပ်', 'key': '누름값', 'y': 'yတည်နေရာအမှတ်', 'output': '출력결과', 'result': 'ရလဒ်', 'client': 'လက်ခံစက်', 'line': 'စာကြောင်း', 'stream': 'စီးကြောင်းတန်ဖိုး', 'name': 'အမည်', 'value': 'တန်ဖိုး', 'receive': 'စာပို့ချက်လက်ခံရယူ', 'report': '검증기록', 'work': 'လုပ်ဆောင်လမ်း', 'qmp': '모의제어접속'}
